// generar_284_actividad_acorde_y_tamano_en_vet_FIX.js
// CHIQUI Entre Señales — Actividad acorde a tamaño/edad + tamaño en /vet
//
// ⚠️ ESTE REEMPLAZA al generar_283, que fallaba el build de Vercel con
//    "Cannot find name 'mascotaNacimiento'". El error: en Análisis la
//    fecha de nacimiento NO es una variable suelta (ese nombre existe
//    en el registro diario), vive en el objeto mascota. Corregido a
//    mascota?.fecha_nacimiento. NO corras el 283 — corre SOLO este.
//
// Contenido (idéntico al 283, ya corregido):
//
// 1) RESUMEN DE CHIQUI: línea de actividad contextualizada (perros).
//    Compara el promedio diario registrado (paseo + enriquecimiento,
//    30 días) contra un rango orientativo por etapa de vida y tamaño:
//      · Cachorro (<12m): sesiones cortas varias veces al día.
//      · Adulto: 30–45 min (pequeño), 30–90 (mediano), 1–2 h (grande).
//      · Senior (7+): paseos suaves, 20–40 min.
//    Tono cuidadoso, con tres resguardos: dice "según lo que
//    registraste" (no afirma sedentarismo), deja espacio a que la baja
//    actividad sea salud y no pereza (deriva al vet), y trata la regla
//    de 5 min/mes como orientación, no como límite médico. Solo en
//    perros con actividad registrada > 0.
//
// 2) FICHA DEL VETERINARIO: tamaño junto al peso (Muy pequeño /
//    Pequeño / Mediano / Grande / Gigante, con su rango de kg). Dato
//    objetivo, sin interpretación. Gatos → "—".
//
// No hay SQL.
//
// Uso:
//   node generar_284_actividad_acorde_y_tamano_en_vet_FIX.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/analisis/page.tsx",
    base64: ""
  },
  {
    ruta: "app/vet/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
